/**
 * The stand-in catalogue: every slot x tier x rarity, dishes of every tier and
 * rarity, the traits, the tree's additions and a few walls, generated by the
 * rules of PROGRESSION 4.2-4.7 and 5.7 and BODY_CLOCKS 5-7 from the data in
 * fixture-rules.json. It is never content: the prover's verdict on content
 * never reads it. Each thing carries what its rarity allows (5.7):
 * - common: one effect at its stat's smallest step (the tier-1 value), or a
 *   trait (strength 1 at any tier);
 * - uncommon: one effect at the top of its band, or one trait;
 * - rare and legendary: one or two, a trait at most once;
 * - a garment with a trait, uncommon or better, also comes as a master piece.
 */
import { readFileSync } from 'node:fs';
import { masteryMs } from './curve';
import type { Catalogue, Dish, Effect, Piece, Wall } from './catalogue';
import { CATEGORIES, type Category, RARITY_NAMES, type Rules } from './rules';

export interface FixtureRules {
  schools: { id: string; first: boolean; t1_ms?: number }[];
  slots: { id: string; count: number; cats: Category[] }[];
  traits: { name: string; answers: string; slots: string[]; maker: string }[];
  piece_full_by_tier: Record<string, number[]>;
  piece_makers: Record<string, string>;
  dish_effects: { kind: string; cat: Category; by_tier: number[] }[];
  tree_by_band: Record<Category, number[]>;
  xp_sources: { source: string; permille: number }[];
  effect_edges: [string, string][];
  walls: {
    id: string;
    band: number;
    conditions: string[];
    grade: number;
    length_gh: number;
    timer_gh?: number;
    by: 'move' | 'work';
    needs_level?: number;
    witness?: { pieces: string[]; dishes: string[] };
  }[];
}

export const FIXTURE_RULES = new URL('./fixture-rules.json', import.meta.url);

export function readFixtureRules(): FixtureRules {
  return JSON.parse(readFileSync(FIXTURE_RULES, 'utf8')) as FixtureRules;
}

const pairs = <T>(list: readonly T[]): [T, T][] => list.flatMap((a, i) => list.slice(i + 1).map((c) => [a, c] as [T, T]));

/** A rarity's strength of a full value: common the smallest step, the rest the top of its band (5.7), rounded down. */
function strength(rules: Rules, full: number[], tier: number, rarity: number): number {
  if (rarity === 0) return full[0] ?? 0;
  const hi = rules.rarityBandPermille[rarity]?.[1] ?? 1000;
  return Math.trunc(((full[tier - 1] ?? 0) * hi) / 1000);
}

export function fixtureCatalogue(rules: Rules, data: FixtureRules = readFixtureRules()): Catalogue {
  const tiers = rules.bands;
  const pieces: Piece[] = [];
  for (const slot of data.slots) {
    const traits = data.traits.filter((t) => t.slots.includes(slot.id));
    const atoms: string[] = [...slot.cats, ...traits.map((t) => t.name)];
    for (let tier = 1; tier <= tiers; tier++) {
      for (let rarity = 0; rarity < RARITY_NAMES.length; rarity++) {
        const max = rules.rarityEffectsMax[rarity] ?? 1;
        const sets: string[][] = atoms.map((a) => [a]);
        if (max >= 2) for (const [a, c] of pairs(atoms)) if (!(traits.some((t) => t.name === a) && traits.some((t) => t.name === c))) sets.push([a, c]);
        for (const set of sets) {
          const trait = set.find((a) => traits.some((t) => t.name === a));
          const effects: Effect[] = set
            .filter((a) => a !== trait)
            .map((a) => ({ kind: a, cat: a as Category, value: strength(rules, data.piece_full_by_tier[a] ?? [], tier, rarity) }));
          const base = `${slot.id}.t${tier}.${RARITY_NAMES[rarity]}.${set.join('+')}`;
          const maker = trait ? data.traits.find((t) => t.name === trait)!.maker : data.piece_makers[slot.id];
          const piece: Piece = { id: base, slot: slot.id, tier, rarity, master: false, effects, ...(trait ? { trait } : {}), ...(maker ? { maker } : {}) };
          pieces.push(piece);
          if (trait && rarity >= 1) pieces.push({ ...piece, id: `${base}.master`, master: true });
        }
      }
    }
  }
  const dishes: Dish[] = [];
  const answers = data.traits.map((t) => ({ kind: t.name, answers: t.answers }));
  const dishAtoms = [...data.dish_effects.map((e) => e.kind), ...answers.map((a) => a.kind)];
  for (let tier = 1; tier <= tiers; tier++) {
    for (let rarity = 0; rarity < RARITY_NAMES.length; rarity++) {
      const max = Math.min(2, rules.rarityEffectsMax[rarity] ?? 1);
      const sets: string[][] = dishAtoms.map((a) => [a]);
      // no ingredient carries two place answers, so no dish does (BODY_CLOCKS 7.4)
      if (max >= 2) for (const [a, c] of pairs(dishAtoms)) if (!(answers.some((x) => x.kind === a) && answers.some((x) => x.kind === c))) sets.push([a, c]);
      for (const set of sets) {
        const answer = answers.find((x) => set.includes(x.kind));
        const effects: Effect[] = set.map((k) => {
          const row = data.dish_effects.find((e) => e.kind === k);
          return row ? { kind: k, cat: row.cat, value: strength(rules, row.by_tier, tier, rarity) } : { kind: k, cat: 'place' as const, value: rules.dishPlaceStep };
        });
        dishes.push({ id: `dish.t${tier}.${RARITY_NAMES[rarity]}.${set.join('+')}`, tier, rarity, effects, ...(answer ? { answers: answer.answers } : {}), maker: 'cooking' });
      }
    }
  }
  const walls: Wall[] = data.walls.map((w) => ({
    id: w.id,
    band: w.band,
    conditions: [...w.conditions],
    grade: w.grade,
    lengthMin: w.length_gh * 60,
    by: w.by,
    ...(w.timer_gh !== undefined ? { timerMin: w.timer_gh * 60 } : {}),
    ...(w.needs_level !== undefined ? { needsLevel: w.needs_level } : {}),
    ...(w.witness ? { witness: { pieces: [...w.witness.pieces], dishes: [...w.witness.dishes] } } : {}),
  }));
  const full: Record<string, number[]> = { ...data.piece_full_by_tier };
  for (const e of data.dish_effects) full[`dish:${e.kind}`] = [...e.by_tier];
  const steps: Record<string, number> = {};
  for (const c of CATEGORIES) if (data.piece_full_by_tier[c]) steps[c] = data.piece_full_by_tier[c][0] ?? 0;
  for (const e of data.dish_effects) steps[e.kind] = e.by_tier[0] ?? 0;
  for (const a of answers) steps[a.kind] = rules.dishPlaceStep;
  return {
    source: 'fixture',
    schools: data.schools.map((s) => ({ id: s.id, masteryMs: masteryMs(rules, s.t1_ms ?? rules.t1Ms), first: s.first })),
    slots: data.slots.map((s) => ({ id: s.id, count: s.count })),
    traits: data.traits.map((t) => ({ name: t.name, answers: t.answers, slots: [...t.slots] })),
    pieces,
    dishes,
    walls,
    tree: data.tree_by_band,
    edges: data.effect_edges.map(([a, c]) => [a, c] as [string, string]),
    xpSources: data.xp_sources.map((s) => ({ ...s })),
    names: [...new Set([...CATEGORIES, ...dishAtoms, ...data.effect_edges.map(([a]) => a)])].sort(),
    steps,
    full,
  };
}
